function userKey(t, expected) {
  if (t.iss !== expected.iss || t.aud !== expected.clientId) throw new Error("wrong issuer/audience");
  if (t.nonce !== expected.nonce) throw new Error("nonce mismatch");
  return `${t.iss}|${t.sub}`;    // identify users by (iss, sub)
}
console.log(userKey(idToken, { iss: "https://accounts.example.com", clientId: "web-app", nonce: "n-0S6_WzA2Mj" }));
// https://accounts.example.com|248289761001

// Fetch and cache a client-credentials token (Node 22+, global fetch)
let cached = { token: null, expiresAt: 0 };

async function getServiceToken() {
  if (cached.token && Date.now() < cached.expiresAt - 60_000) return cached.token;
  const res = await fetch("https://auth.example.com/oauth/token", {
    method: "POST",
    headers: {
      Authorization: "Basic " + Buffer.from(
        `${process.env.CLIENT_ID}:${process.env.CLIENT_SECRET}`).toString("base64"),
    },
    body: new URLSearchParams({ grant_type: "client_credentials", scope: "invoices.read" }),
  });
  if (!res.ok) throw new Error(`token endpoint: ${res.status}`);
  const { access_token, expires_in } = await res.json();
  cached = { token: access_token, expiresAt: Date.now() + expires_in * 1000 };
  return access_token;
}
