import { generateKeyPair, exportJWK, SignJWT, jwtVerify, createLocalJWKSet } from "jose";

// Simulate the authorization server: a key pair and its JWKS
const { publicKey, privateKey } = await generateKeyPair("ES256");
const jwks = { keys: [{ ...(await exportJWK(publicKey)), kid: "k1", alg: "ES256" }] };
const token = await new SignJWT({ scope: "orders.read" })
  .setProtectedHeader({ alg: "ES256", kid: "k1", typ: "at+jwt" })
  .setIssuer("https://auth.example.com").setAudience("https://api.example.com")
  .setSubject("user-42").setIssuedAt().setExpirationTime("15m").sign(privateKey);

// The API: in production use createRemoteJWKSet(new URL(jwks_uri))
const JWKS = createLocalJWKSet(jwks);
const { payload } = await jwtVerify(token, JWKS, {
  issuer: "https://auth.example.com",
  audience: "https://api.example.com",
  algorithms: ["ES256"],
  typ: "at+jwt",
  clockTolerance: 30,
});
console.log(payload.sub, payload.scope); // user-42 orders.read

// Express-style middleware (framework-agnostic idea)
function requireScope(scope) {
  return (req, res, next) => {
    const granted = (req.auth?.scope ?? "").split(" ");
    if (!req.auth) return res.status(401).set("WWW-Authenticate", 'Bearer').end();
    if (!granted.includes(scope)) {
      return res.status(403)
        .set("WWW-Authenticate", `Bearer error="insufficient_scope", scope="${scope}"`).end();
    }
    next();
  };
}

