// RP-initiated logout URL (when the provider supports end_session_endpoint)
function logoutUrl(cfg, idToken) {
  const u = new URL(cfg.end_session_endpoint);
  u.searchParams.set("id_token_hint", idToken);
  u.searchParams.set("post_logout_redirect_uri", "https://app.example.com/bye");
  return u.toString();
}

import { SignJWT, jwtVerify, generateSecret, UnsecuredJWT } from "jose";

const secret = await generateSecret("HS256");
const opts = { algorithms: ["HS256"], issuer: "auth", audience: "api" };

// alg=none token: jose rejects it because 'none' is not an allowed algorithm
const unsigned = new UnsecuredJWT({ sub: "admin" }).setIssuer("auth").setAudience("api").encode();
await jwtVerify(unsigned, secret, opts).catch((e) => console.log(e.code));
// ERR_JOSE_ALG_NOT_ALLOWED

// right key, wrong audience (token for another service)
const other = await new SignJWT({ sub: "u1" }).setProtectedHeader({ alg: "HS256" })
  .setIssuer("auth").setAudience("billing").setExpirationTime("5m").sign(secret);
await jwtVerify(other, secret, opts).catch((e) => console.log(e.code, e.claim));
// ERR_JWT_CLAIM_VALIDATION_FAILED aud

import { generateKeyPair, exportJWK, SignJWT, calculateJwkThumbprint } from "jose";
import { createHash, randomUUID } from "node:crypto";

const { publicKey, privateKey } = await generateKeyPair("ES256");
const jwk = await exportJWK(publicKey);

async function dpopProof(method, url, accessToken) {
  const claims = { htm: method, htu: url, jti: randomUUID() };
  if (accessToken) claims.ath = createHash("sha256").update(accessToken).digest("base64url");
  return new SignJWT(claims)
    .setProtectedHeader({ typ: "dpop+jwt", alg: "ES256", jwk })
    .setIssuedAt().sign(privateKey);
}

const proof = await dpopProof("GET", "https://api.example.com/orders", "eyJ...token");
console.log(proof.split(".").length); // 3
// The AS binds the token to this thumbprint (cnf.jkt):
console.log((await calculateJwkThumbprint(jwk)).length); // 43
